import{_ as e,c as s,o,ag as i}from"./chunks/framework.Sr95JMjc.js";const h=JSON.parse('{"title":"System Instructions","description":"","frontmatter":{},"headers":[],"relativePath":"AGENTS.md","filePath":"AGENTS.md","lastUpdated":1777107917000}'),l={name:"AGENTS.md"};function a(r,t,n,c,d,u){return o(),s("div",null,[...t[0]||(t[0]=[i('<h1 id="system-instructions" tabindex="-1">System Instructions <a class="header-anchor" href="#system-instructions" aria-label="Permalink to &quot;System Instructions&quot;">​</a></h1><p>모든 답변은 한국어로 작성해주세요. 에이전트는 절대로 <code>git add</code> 및 <code>git commit</code> 명령어를 직접 실행하거나 시도하지 마세요. 형상 관리는 사용자가 직접 수행합니다.</p><h3 id="깃허브-작업-지침-github-operations" tabindex="-1">깃허브 작업 지침 (GitHub Operations) <a class="header-anchor" href="#깃허브-작업-지침-github-operations" aria-label="Permalink to &quot;깃허브 작업 지침 (GitHub Operations)&quot;">​</a></h3><ul><li><strong>이슈 관리 (Issues)</strong>: <ul><li>하위 이슈(Sub-issue) 관리가 필요한 경우 <code>yahsan2/gh-sub-issue</code> 확장을 사용합니다.</li><li>상위 이슈에 연결 시 <code>gh sub-issue add &lt;상위-번호&gt; &lt;하위-번호&gt;</code>를 실행합니다. (미설치 시 <code>gh extension install</code> 선행)</li></ul></li><li><strong>풀 리퀘스트 (Pull Requests)</strong>: <ul><li>PR 생성 시 본문에 <code>Resolves #&lt;이슈-번호&gt;</code> 또는 <code>Closes #&lt;이슈-번호&gt;</code>를 포함하여 이슈를 자동으로 연결하고 닫히도록 합니다.</li><li>최초 PR을 생성할 때에는 <code>gh pr create --draft</code>를 사용하여 Draft PR로 생성합니다.</li><li>PR 본문 하단에는 작업을 수행한 에이전트 이름과 사용된 모델 정보를 기재합니다.</li></ul></li><li><strong>댓글 및 소통 (Communication)</strong>: <ul><li>이슈나 PR에 댓글을 남길 때는 최대한 간결한 말투로 작업의 목적과 변경 사항을 요약하여 기재합니다. 장황한 설명이나 불필요한 수식어 사용을 금지합니다.</li><li>이슈에 댓글을 작성할 때는 이슈 작성자(@author)를 멘션합니다.</li><li>PR에 댓글을 작성할 때는 리뷰어(@reviewers)를 멘션합니다.</li></ul></li><li><strong>계정 관리 (Account Management)</strong>: <ul><li>이 프로젝트의 모든 작업은 <code>kdevkr</code> 계정을 사용해야 합니다. 작업 시작 전 <code>gh auth status</code>로 확인하고, 필요시 <code>gh auth switch --user kdevkr</code> 명령어를 사용하여 계정을 전환하세요.</li></ul></li></ul>',4)])])}const m=e(l,[["render",a]]);expo